"""Sources du bloc 01. Relancer remplace les supports et notebooks générés."""
from pathlib import Path
import json, html
R = Path(__file__).resolve().parents[1]
def write(path, text):
    p=R/path; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(text,encoding='utf-8')
def code(s):
    label = 'Terminal · dossier sandbox-notebook' if s.startswith('docker ') else 'Python · sandbox-notebook'
    return '<div class="code-block"><span class="code-label">'+label+'</span><pre tabindex="0"><code>'+html.escape(s)+'</code></pre></div>'
def table(headers,rows): return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def details(title,body): return '<details><summary>'+title+'</summary>'+body+'</details>'
def head(title,prefix='..',script=True):
    return f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f7f8f2"><title>{title} — Le labo Matplotlib</title><link rel="stylesheet" href="{prefix}/assets/site.css"><link rel="stylesheet" href="{prefix}/assets/tableau.css"><link rel="stylesheet" href="{prefix}/assets/matplotlib.css">{f'<script src="{prefix}/assets/cours.js" defer></script>' if script else ''}</head><body><a class="skip-link" href="#contenu">Aller au contenu</a><header class="site-header"><a class="brand" href="{prefix}/index.html"><span class="brand-icon" aria-hidden="true">mp.</span> Le labo Matplotlib</a><a class="back-link" href="{prefix}/index.html">← Le parcours</a></header>'''
def foot(prefix='..'): return f'<footer class="site-footer"><span>Le labo Matplotlib / NEXA</span><a href="{prefix}/index.html">Comprendre, puis pratiquer.</a></footer></body></html>'
def page(title,hero,subtitle,sections,meta='Bases déjà acquises · Bloc 01 · 2 h 30'):
    nav=''.join(f'<a href="#{id}"><span>{i:02}</span>{label}</a>' for i,(id,label,_) in enumerate(sections,1))
    body=''.join(f'<section class="course-section" id="{id}"><p class="eyebrow">Bloc 01 <span>/</span> {i:02} · {label}</p>{content}</section>' for i,(id,label,content) in enumerate(sections,1))
    return head(title)+f'<main class="course-main" id="contenu"><div class="course-intro"><p class="eyebrow">Matplotlib · De la question à la figure</p><h1>{hero}</h1><p>{subtitle}</p><div class="meta">'+''.join(f'<span>{m}</span>' for m in meta.split(' · '))+f'</div></div><div class="course-layout"><nav class="course-nav" aria-label="Étapes du bloc"><p class="eyebrow">Votre parcours</p>{nav}<a class="download-link" href="../data/sandbox-notebook.zip" download>↓ Sandbox apprenant</a><a href="../data/commandes.csv" download>↓ Les données CSV</a></nav><div class="course-content">{body}</div></div></main>'+foot()

