# Notebooks : une même source pour les exercices du cours et du carnet.
def md(s): return {'cell_type':'markdown','metadata':{},'source':s.splitlines(keepends=True)}
def py(s): return {'cell_type':'code','execution_count':None,'metadata':{},'outputs':[],'source':s.splitlines(keepends=True)}
def nb(cells):
    for i,c in enumerate(cells): c['id']=f'bloc01-{i:03}'
    return json.dumps({'cells':cells,'metadata':{'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3.12'}},'nbformat':4,'nbformat_minor':5},ensure_ascii=False,indent=1)+'\n'
intro=[md('# Bloc 01 — Construire un graphique fiable\n\n**NEXA · 2 h 30 · Bases de Matplotlib déjà acquises.**\n\nObjectif : préparer une mesure, utiliser Figure / Axes, produire des barres lisibles, vérifier et exporter.\n\nProjet : le carnet visuel d’une boutique fictive. Question : quelles catégories et quels produits réalisent le plus de ventes ?\n\nUne ligne = une ligne de vente ; 60 lignes, 30 commandes ; du 1er au 30 janvier 2026. Données identiques au TP Tableau. Ventes = Quantite × Prix_unitaire × (1 − Remise), en euros.\n\nExécutez les cellules dans l’ordre avec Maj + Entrée. Les cellules « À vous » sont à compléter ; une exécution sans erreur de ces cellules vides ne signifie pas que le travail est fini.'),md('## 1. Charger et vérifier\nLe code repère la racine, lit le CSV et prépare le dossier des exports. Résultat attendu : 60, 30, puis 45831.0. Si le chemin manque, conservez data et notebooks dans la même sandbox.'),py(SETUP),md('## 2. Préparer les données\ngroupby regroupe les lignes ; sum additionne les montants ; sort_values trie les montants avec leur index.\n\nAttendu : Accessoires 1752.50, Mobilier 13302.50, Informatique 30776.00. La somme doit rester 45831.'),py(AGG),md('## 3. Passer à Figure / Axes\nfig est le document ; ax est sa zone de tracé. barh reçoit les noms et montants dans le même ordre. Le tri croissant place la plus grande barre en haut.\n\nLe titre donne un constat, les labels donnent les dimensions et l’unité, xlim conserve zéro, grid guide la lecture, suptitle nomme le périmètre. savefig exporte cette Figure à 150 dpi avant show.\n\n**Limite :** il s’agit de ventes, pas de bénéfices.\n\nPrédisez l’image avant d’exécuter.'),py(PLOT),md('## 4. Filtrer avant de regrouper\nLa comparaison crée un masque ; .loc retient le Sud sans modifier ventes. Reprenez ce principe dans l’exercice 2.'),py('sud = ventes.loc[ventes["Region"] == "Sud"]\npar_categorie_sud = sud.groupby("Categorie")["Ventes"].sum().sort_values()\nprint(par_categorie_sud)')]
for corrected in (False,True):
    cells=list(intro)
    if corrected: cells=[md('# Correction formateur\nSolutions exécutables. Consulter après un essai autonome.')]+cells
    for i,e in enumerate(EX,1):
        cells.append(md(f'## Exercice {i} — {e["title"]}\n\n**{e["level"]}**\n\n**Objectif :** {e["objective"]}\n\n**Prérequis :** {e["prereq"]}\n\n{e["statement"]}\n\n**Contraintes :** {e["constraint"]}\n\n**Livrable :** {e["deliverable"]}\n\n**Réussite :** {e["success"]}\n\n'+ '\n\n'.join(f'<details><summary>Indice {j}</summary>{h}</details>' for j,h in enumerate(e['hints'],1))))
        if corrected:
            if i==3: cells.extend([md('### Code erroné pour comparaison'),py(BUG)])
            cells.extend([py(e['solution']),md('### Correction expliquée\n'+e['explanation'])])
        else:
            cells.extend([md('### Ma prédiction / ma démarche\nÀ compléter avant l’exécution.'),py(e['starter']),md('### Mon résultat, ma justification et ma limite\nÀ compléter après vérification.')])
    cells.append(md('## Avant la remise\n- [ ] J’ai complété les quatre exercices et mes commentaires.\n- [ ] J’ai vérifié les associations noms–montants.\n- [ ] Mes quatre PNG sont dans resultats.\n- [ ] Les titres précisent la question et le périmètre.\n- [ ] J’ai redémarré le noyau puis exécuté toutes les cellules.\n- [ ] Ma conclusion distingue ventes et bénéfice.\n\n**Pour la suite :** conserver ce notebook, ses exports et le CSV. Le prochain bloc prolongera le même carnet avec les dates et les périmètres.\n\nRéférences : [Matplotlib](https://matplotlib.org/stable/users/explain/quick_start.html), [pandas : tri](https://pandas.pydata.org/docs/reference/api/pandas.Series.sort_values.html).'))
    write('sandbox-notebook/'+('corrections/01_graphiques_fiables_corrige.ipynb' if corrected else 'notebooks/01_graphiques_fiables.ipynb'),nb(cells))
